// ===== WAVE 4 PROFILER (fable-lag) ==========================================
// SOTADAW_PROF=<hz> arms a SIGPROF sampler: the box denies every external
// profiler (yama ptrace_scope=1 blocks gdb attach even on own processes,
// kernel.perf_event_paranoid=4 blocks perf, no valgrind installed) — so the
// binary carries its own. Samples = raw return addresses appended to a static
// ring; dumped to <ipc>/prof.samples (+ /proc/self/maps copy) at shutdown;
// tools/prof_resolve.py folds them through addr2line into a cost tree.
// ITIMER_PROF ticks on CPU time, so samples land on whichever thread burns —
// exactly the attribution question. Zero cost unless armed.
namespace sotaprof
{
#ifdef _WIN32
    // PORT_SPEC.md: SIGPROF/backtrace are POSIX — the self-profiler is a no-op
    // on Windows (external profilers exist there; this rig was built for a box
    // that denies them).
    static void arm() {}
    static void dump() {}
#else
    static void* buf[1 << 21];                    // 16MB of addresses
    static std::atomic<int> used { 0 };
    static void onProf (int)
    {
        void* fr[48];
        const int n = ::backtrace (fr, 48);
        if (n <= 0) return;
        const int base = used.fetch_add (n + 1, std::memory_order_relaxed);
        if (base + n + 1 >= (int) (sizeof (buf) / sizeof (void*))) return;
        buf[base] = (void*) (intptr_t) n;
        for (int i = 0; i < n; ++i) buf[base + 1 + i] = fr[i];
    }
    static void arm()
    {
        const char* hz = std::getenv ("SOTADAW_PROF");
        if (hz == nullptr) return;
        { void* warm[4]; ::backtrace (warm, 4); }  // preload libgcc OUTSIDE the handler
        struct sigaction sa = {};
        sa.sa_handler = onProf;
        sa.sa_flags = SA_RESTART;
        sigaction (SIGPROF, &sa, nullptr);
        const int us = juce::jlimit (2000, 100000, 1000000 / juce::jmax (1, atoi (hz)));
        itimerval tv {{ 0, us }, { 0, us }};
        setitimer (ITIMER_PROF, &tv, nullptr);
        std::printf ("PROF armed every %dus\n", us); std::fflush (stdout);
    }
    static void dump()
    {
        if (std::getenv ("SOTADAW_PROF") == nullptr) return;
        itimerval off {}; setitimer (ITIMER_PROF, &off, nullptr);
        const char* ipc = std::getenv ("SOTADAW_IPC");
        const auto dir = ipc != nullptr ? juce::File (juce::String (ipc))
                                        : sotadaw::sotadawRoot().getChildFile ("agent/ipc");
        dir.createDirectory();
        juce::MemoryOutputStream out;
        const int n = juce::jmin (used.load(), (int) (sizeof (buf) / sizeof (void*)));
        for (int i = 0; i < n; )
        {
            const int fn = (int) (intptr_t) buf[i];
            if (fn <= 0 || fn > 48) break;
            for (int k = 0; k < fn; ++k)
            {
                out << juce::String::toHexString ((juce::int64) (intptr_t) buf[i + 1 + k]);
                if (k + 1 < fn) out << " ";
            }
            out << "\n";
            i += fn + 1;
        }
        dir.getChildFile ("prof.samples").replaceWithData (out.getData(), out.getDataSize());
        {   // /proc files stat as size 0 — copyFileTo copies nothing (and clobbers
            // an outside snapshot). Stream-read instead.
            juce::FileInputStream mi (juce::File ("/proc/self/maps"));
            if (mi.openedOk())
                dir.getChildFile ("prof.maps").replaceWithText (mi.readEntireStreamAsString());
        }
        std::printf ("PROF dumped %d words -> %s\n", n,
                     dir.getChildFile ("prof.samples").getFullPathName().toRawUTF8());
        std::fflush (stdout);
    }
#endif // _WIN32
}

