            if (lastJamTake.isEmpty()) return;
            setStatus ("merging " + lastJamTake + " into " + songName + "...");
            writeRequest ("verb", "\"verb\": \"keep_jam\", \"args\": {\"take\": "
                          + juce::JSON::toString (juce::var (lastJamTake)) + "},");
            lastJamTake.clear();
