    juce::String snapOverflowCensus()  // rig: no visible row may paint outside laneArea
    {
        int vis = 0, zero = 0, banded = 0, bleed = 0;
        auto inside = [this] (int yTop, int yBot)
        { return yTop >= laneArea.getY() - 1 && yBot <= laneArea.getBottom() + 1; };
        for (auto* l : lanes)
        {
            if (! l->isVisible() || l->getWidth() == 0) { ++zero; continue; }
            ++vis;
            const int pTop = l->getY() + l->clipTopPx;
            const int pBot = l->getY() + juce::jmin (l->clipBotPx, l->getHeight());
            if (l->clipTopPx > 0 || l->clipBotPx < l->getHeight()) ++banded;
            if (! inside (pTop, pBot)) ++bleed;
        }
        int barBleed = 0;
        for (auto* b : groupBars)
            if (b->isVisible() && b->getWidth() > 0
                && ! inside (b->getY(), b->getBottom())) ++barBleed;
        juce::String s;
        s << "lanes=" << lanes.size() << " vis=" << vis << " off=" << zero
          << " banded=" << banded << " bleed=" << bleed << " barbleed=" << barBleed
          << " hist=" << (historyPanel.isVisible() ? 1 : 0)
          << " scale=" << juce::String (laneScale, 2);
        return s;
    }
    juce::String snapLaneCensus()      // rig: DEREF every lane's model — the dangling test
    {
        int modeled = 0;
        for (auto* l : lanes)
            if (l->track != nullptr) { l->trackCol(); ++modeled; }
        juce::String s;
        s << "lanes=" << lanes.size() << " modeled=" << modeled
          << " auditioning=" << (auditioningProposal ? 1 : 0)
          << " streaming=" << (proposalStreaming ? 1 : 0);
        return s;
    }
