    // rig: B4 ENGINE CAPTURE — the REAL Rec flow on an audio lane (THE LANE'S KIND
    // DECIDES); the driver (tools/audio_rec_e2e.py) asserts harvest + json truth.
    // A silent room is a legal take: MACHINERY is asserted, content energy is not.
    // rig: THE PUNCH-IN player half — DC-step click proof, deviceless (pure DSP
    // through the REAL JamPlayer). A hard swap at the line would step 1.0; the
    // crossfade must step ~1/768. Driver: tools/punch_play_e2e.py.
    void rigPlayBench (bool on)
    {   // WAVE 4 LAG BENCH hands: the REAL play door, no shortcuts — whatever
        // playback costs the user, it costs the bench.
        // SOTADAW_PLAYBENCH_STATE=agent|roll reproduces a user surface first.
        if (edit == nullptr) return;
        if (on)
            if (const char* st = std::getenv ("SOTADAW_PLAYBENCH_STATE"))
            {
                if (juce::String (st) == "agent") setAgentMode (true);
                if (juce::String (st) == "roll")  openRoll (1, true);
            }
        if (on != edit->getTransport().isPlaying()) togglePlay();
    }
    void rigPunchPlay()
    {
        auto dir = ipcDir.getChildFile ("punchplay");
        dir.createDirectory();
        auto writeDc = [] (const juce::File& f, float dc, double secs)
        {
            f.deleteFile();
            juce::WavAudioFormat wf;
            std::unique_ptr<juce::AudioFormatWriter> w (wf.createWriterFor (
                new juce::FileOutputStream (f), 44100.0, 2, 16, {}, 0));
            juce::AudioBuffer<float> b (2, (int) (44100 * secs));
            for (int ch = 0; ch < 2; ++ch)
                juce::FloatVectorOperations::fill (b.getWritePointer (ch), dc,
                                                   b.getNumSamples());
            w->writeFromAudioSampleBuffer (b, 0, b.getNumSamples());
        };
        auto pf = dir.getChildFile ("phrase.wav");
        auto uf = dir.getChildFile ("punch.wav");
        writeDc (pf, 0.5f, 2.0);
        writeDc (uf, -0.5f, 1.0);
        sotadaw::JamPlayer jp (engine->getDeviceManager().deviceManager);
        jp.noDevice = true;
        jp.enqueue (pf);
        const bool armed = jp.punchIn (0, 0.5, uf);
        juce::AudioBuffer<float> outBuf (2, 512);
        std::vector<float> all;
        juce::AudioSource& src = jp;
        src.prepareToPlay (512, 44100.0);
        for (int blocks = 0; blocks < (int) (2.0 * 44100 / 512) + 2; ++blocks)
        {
            juce::AudioSourceChannelInfo ci (&outBuf, 0, 512);
            src.getNextAudioBlock (ci);
            for (int i = 0; i < 512; ++i)
                all.push_back (outBuf.getSample (0, i));
        }
        const bool lateDropped = ! jp.punchIn (0, 0.0, uf);
        const int N = (int) all.size();
        double pre = 0, post = 0;
        for (int i = 0; i < 17640; ++i) pre += all[(size_t) i];
        for (int i = 60000; i < 88000; ++i) post += all[(size_t) i];   // post-fade,
        pre /= 17640.0; post /= 28000.0;                               // pre-stream-end
        float maxStep = 0;
        int crossAt = -1;
        // click scan bounded to the MUSICAL span: past 88200 the set has ended
        // and the source legitimately clears to silence (that edge is the app's
        // stop, not the punch's seam)
        for (int i = 1; i < juce::jmin (N, 88000); ++i)
        {
            maxStep = juce::jmax (maxStep, std::abs (all[(size_t) i] - all[(size_t) (i - 1)]));
            if (crossAt < 0 && all[(size_t) i] < 0.0f) crossAt = i;
        }
        // B6 TAIL + GAIN legs: material past a phrase's MUSICAL length must ring
        // UNDER the next phrase (overlap-add — the send tail never chops at the
        // join), and the BAND fader must scale the whole wire. DC physics: A =
        // 1.0s of 0.5 then 0.5s of 0.25 (its "tail"), musical = 1.0s; B = 1.0s of
        // 0.5. Physical sums: [0,1)=0.5, [1,1.5)=0.75, [1.5,2)=0.5 — all halved
        // by gain 0.5.
        auto writeDc2 = [] (const juce::File& f, float va, double sa, float vb, double sb)
        {
            f.deleteFile();
            juce::WavAudioFormat wf;
            std::unique_ptr<juce::AudioFormatWriter> w (wf.createWriterFor (
                new juce::FileOutputStream (f), 44100.0, 2, 16, {}, 0));
            juce::AudioBuffer<float> b2 (2, (int) (44100 * (sa + sb)));
            const int na = (int) (44100 * sa);
            for (int ch = 0; ch < 2; ++ch)
            {
                juce::FloatVectorOperations::fill (b2.getWritePointer (ch), va, na);
                juce::FloatVectorOperations::fill (b2.getWritePointer (ch) + na, vb,
                                                   b2.getNumSamples() - na);
            }
            w->writeFromAudioSampleBuffer (b2, 0, b2.getNumSamples());
        };
        auto tf = dir.getChildFile ("tail_phrase.wav");
        auto bf = dir.getChildFile ("next_phrase.wav");
        writeDc2 (tf, 0.5f, 1.0, 0.25f, 0.5);
        writeDc (bf, 0.5f, 1.0);
        sotadaw::JamPlayer jp2 (engine->getDeviceManager().deviceManager);
        jp2.noDevice = true;
        jp2.enqueue (tf, 1.0);                     // musical 1.0s -> 0.5s is TAIL
        jp2.enqueue (bf, 1.0);
        jp2.setGain (0.5f);                        // the BAND fader halves the wire
        std::vector<float> all2;
        juce::AudioSource& src2 = jp2;
        src2.prepareToPlay (512, 44100.0);
        for (int blocks = 0; blocks < (int) (2.0 * 44100 / 512) + 2; ++blocks)
        {
            juce::AudioSourceChannelInfo ci2 (&outBuf, 0, 512);
            src2.getNextAudioBlock (ci2);
            for (int i = 0; i < 512; ++i)
                all2.push_back (outBuf.getSample (0, i));
        }
        auto meanOver = [&all2] (double s0, double s1)
        {
            const int a2 = (int) (s0 * 44100), b3 = (int) (s1 * 44100);
            double m = 0;
            for (int i = a2; i < b3 && i < (int) all2.size(); ++i) m += all2[(size_t) i];
            return m / juce::jmax (1, b3 - a2);
        };
        const double tailHead = meanOver (0.10, 0.90);   // 0.25 = 0.5 * gain
        const double tailMix  = meanOver (1.05, 1.45);   // 0.375 = (0.5 + 0.25) * gain
        const double tailAfter = meanOver (1.55, 1.95);  // 0.25: the tail has rung out
        std::cout << "[punchplay] armed=" << (armed ? 1 : 0)
                  << " pre=" << juce::String (pre, 3)
                  << " post=" << juce::String (post, 3)
                  << " maxStep=" << juce::String (maxStep, 5)
                  << " crossAt=" << crossAt
                  << " lateDrop=" << (lateDropped ? 1 : 0)
                  << " tailHead=" << juce::String (tailHead, 3)
                  << " tailMix=" << juce::String (tailMix, 3)
                  << " tailAfter=" << juce::String (tailAfter, 3) << std::endl;
    }

    // rig: THE JAM STRIP — a synthetic conversation painted + machine-dumped
    void rigJamStrip()
    {
        jamStrip.reset();
        jamStrip.markFollow (1);              // exercises the pending-mark path
        jamStrip.addBlock (0, 0.0, 2.0, false);
        jamStrip.addBlock (1, 8.0, 1.0, false);
        jamStrip.addBlock (2, 12.0, 1.0, true);
        jamStrip.addPunch (4.0);
        jamStrip.setProgressPhrase (1.5);     // playedBeats = 8 + 2 = 10
        resized();
    }
