    // THE GLOBAL ACCELERATORS (Chezy 2026-07-08: "ctrl+Z NEEDS to revert, all the
    // regular program shit"): the desktop-standard editing chords must fire NO
    // MATTER what holds focus — a JUCE TextEditor (the agent prompt, the inline
    // ask) has its OWN ctrl+Z/Y text-undo and SWALLOWS the chord before it can
    // bubble to the song. A KeyListener is consulted BEFORE the component's own
    // keyPressed, so installing this on those editors (and the main surface as a
    // belt) makes undo/redo/save reach the SONG from anywhere. Only the true
    // globals are stolen; every other key falls through to the field.
    struct GlobalKeys : juce::KeyListener
    {
        MainComponent& mc;
        explicit GlobalKeys (MainComponent& m) : mc (m) {}
        bool keyPressed (const juce::KeyPress& k, juce::Component*) override
        {
            if (! (k.getModifiers().isCommandDown() || k.getModifiers().isCtrlDown()))
                return false;
            const int kc = k.getKeyCode();
            const bool shift = k.getModifiers().isShiftDown();
            if ((kc == 'Z' || kc == 'z') && ! shift) { mc.undo(); return true; }
            if (((kc == 'Z' || kc == 'z') && shift) || kc == 'Y' || kc == 'y')
                { mc.redo(); return true; }
            if (kc == 'S' || kc == 's')
                { mc.saveNow(); mc.setStatus ("saved " + mc.songName); return true; }
            return false;
        }
    };
